SELECT tenant_id,integration_id,group_binding_id,end_user_id,role,status,revision,source_event_id,source_revision,actor_ref
FROM public.nw_group_memberships
WHERE tenant_id=#{tenant} AND integration_id=#{integration} AND group_binding_id=#{group} AND end_user_id>#{after}
ORDER BY end_user_id LIMIT #{limit}

SELECT tenant_id,integration_id,group_binding_id,agent_id,status,revision,source_event_id,source_revision,actor_ref
FROM public.nw_group_service_agents
WHERE tenant_id=#{tenant} AND integration_id=#{integration} AND group_binding_id=#{group} AND agent_id>#{after}
ORDER BY agent_id LIMIT #{limit}
